<script lang="ts">
	import { goto } from '$app/navigation';
	import type { PageProps } from './$types';
	let { data }: PageProps = $props();
	function currency(value: number) { return new Intl.NumberFormat('en-GB', { style: 'currency', currency: 'GBP', signDisplay: 'always' }).format(value); }
	function navigate(key: 'week' | 'odds', value: string) { const query = new URLSearchParams(); const week = key === 'week' ? value : data.selectedWeek; const odds = key === 'odds' ? value : data.selectedOddsRange; if (week !== 'all') query.set('week', week); if (odds !== 'bettable') query.set('odds', odds); void goto(`/strategies/over-3-5${query.size ? `?${query}` : ''}`); }
</script>
<svelte:head><title>Black Diamond · Over 3.5 strategies</title><meta name="description" content="Historical Over 3.5 goals strategy performance." /></svelte:head>
<main class="min-h-screen bg-slate-100"><div class="mx-auto max-w-5xl px-3 py-4 sm:px-6 sm:py-6"><header class="mb-4 sm:mb-6"><h1 class="text-xl font-semibold tracking-tight text-slate-950 sm:text-3xl">Over 3.5 goals strategies</h1><p class="mt-1 text-xs text-slate-600 sm:text-sm">Historical performance for high-scoring recent form.</p></header><section class="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><p class="text-[10px] font-bold uppercase tracking-wide text-slate-500">Over 3.5 strategy explorer</p><h2 class="mt-1 text-base font-semibold text-slate-950">High-scoring and defensive filters</h2><p class="mt-1 text-xs leading-5 text-slate-600">Flat £1 stakes and stored pre-match Over 3.5 odds. Rows with fewer than {data.minimumBetsForRanking} qualifying bets are excluded and ranked by profit.</p><div class="mt-4 flex flex-wrap gap-3"><select value={data.selectedWeek} onchange={(event) => navigate('week', event.currentTarget.value)} class="rounded-lg border border-slate-300 bg-white px-2 py-1.5 text-xs"><option value="all">All weeks</option>{#each data.availableWeeks as week}<option value={week}>{week}</option>{/each}</select><select value={data.selectedOddsRange} onchange={(event) => navigate('odds', event.currentTarget.value)} class="rounded-lg border border-slate-300 bg-white px-2 py-1.5 text-xs"><option value="bettable">Your minimum · 2.20+</option><option value="all">All odds</option>{#each data.oddsRanges as range}<option value={range.id}>{range.label}</option>{/each}</select></div><div class="mt-4 overflow-x-auto rounded-lg border border-slate-200"><table class="w-full min-w-[680px] table-fixed text-left text-xs"><thead class="bg-slate-50 text-[10px] uppercase tracking-wide text-slate-500"><tr><th class="px-3 py-2">Variation</th><th class="px-3 py-2 text-right">Bets</th><th class="px-3 py-2 text-right">W / L</th><th class="px-3 py-2 text-right">P / L</th><th class="px-3 py-2 text-right">ROI</th></tr></thead><tbody class="divide-y divide-slate-100">{#each data.results as result (result.id)}<tr><td class="px-3 py-2"><a href={`/strategies/listings?query=${result.id}`} class="font-medium text-slate-950 hover:underline">{result.title}</a><p class="mt-0.5 text-[11px] text-slate-500">{result.description}</p></td><td class="px-3 py-2 text-right">{result.bets}</td><td class="px-3 py-2 text-right">{result.wins} / {result.losses}</td><td class="px-3 py-2 text-right font-semibold" class:text-emerald-700={result.profit > 0} class:text-rose-700={result.profit < 0}>{currency(result.profit)}</td><td class="px-3 py-2 text-right">{result.returnOnInvestment === null ? '—' : `${result.returnOnInvestment.toFixed(1)}%`}</td></tr>{/each}</tbody></table></div></section></div></main>
